"""
Builds benchmarks/forest.bb with blitzcc, runs it and prints the frame times and what the frames cost: a dense night forest with a winding river, 600000
grass blades, pebbles, a bridge lit by a torch, glowing insects with lights, bump-mapped ground and bark, a river picture drawn on the GPU every frame and a
fullscreen bloom (all with render targets). The result is also saved as JSON (and added to a CSV) in benchmarks/results/.

    python3 benchmarks/forest.py [--trees N] [--grass N] [--pebbles N] [--insects N] [--no-bloom] [common options, see --help]

--trees defaults to $BENCH_TREES or 1800, --grass (blades) to $BENCH_GRASS or 600000, --pebbles to $BENCH_PEBBLES or 14000, --insects to $BENCH_INSECTS or 40,
--frames to $BENCH_FRAMES or 600. "--quick" is a small scene and 30 frames for a look whether it works. The camera walks along the path to the bridge and
back (1200 frames), so a result is the same for the same --frames and --seed. -d builds without optimization (which BLITZLLVM_PROFILE_FPS profiling needs
together with --profile); the build configuration is part of the result so runs are not mixed up.

The original Blitz3D works too, so that its speed can be compared: --blitzcc C:\\Blitz3D\\bin\\blitzcc.exe (BLITZPATH is set to the folder with bin\\ in
it unless it is set). It has no -O3 and no --profile, no draw counters (they are 0), no samplers (the BlitzLLVM build filters the textures anisotropically),
and its window can be at most 2048 in each direction. The scene uses at most a few hundred sprites and a surface never holds more than 65535 vertices.

Without a display the program runs under xvfb-run, which with Mesa means llvmpipe: the times are then mostly the CPU
rasterizing and only a smoke test. The counts (draws, triangles) are exact on any GPU.
"""
import os
import benchutil


def main():
    runner = benchutil.Runner("forest", __doc__, frames=600)
    p = runner.parser
    p.add_argument("--trees", type=int, default=int(os.environ.get("BENCH_TREES", 1800)))
    p.add_argument("--grass", type=int, default=int(os.environ.get("BENCH_GRASS", 600000)))
    p.add_argument("--pebbles", type=int, default=int(os.environ.get("BENCH_PEBBLES", 14000)))
    p.add_argument("--insects", type=int, default=int(os.environ.get("BENCH_INSECTS", 40)))
    p.add_argument("--no-bloom", action="store_true", help="without the fullscreen bloom")
    args = runner.parse()
    if args.quick:
        args.trees, args.grass, args.pebbles, args.insects = 100, 20000, 500, 10
    env = {"BENCH_TREES": args.trees, "BENCH_GRASS": args.grass, "BENCH_PEBBLES": args.pebbles, "BENCH_INSECTS": args.insects}
    if args.no_bloom:
        env["BENCH_BLOOM"] = 0
    values = runner.run(env, "%d trees, %d grass blades, %d pebbles, %d insects%s" % (args.trees, args.grass, args.pebbles, args.insects,
                                                                                    ", no bloom" if args.no_bloom else ""))
    runner.report(["scene       %d trees, %d grass blades, %d pebbles, %d insects%s" % (values["trees"], values["tufts"], values["pebbles"], values["insects"],
                                                                                    ", no bloom" if args.no_bloom else "")],
                  update="the walk, water, insects, wind and torch")
    runner.save(str(args.grass), ("trees", "tufts", "pebbles", "insects", "bloom"))


if __name__ == "__main__":
    main()
